entries[1247279] = { ["name"] = "Tigeraugengebräu", ["text"] = "Sofort\nFür alle 3 Chi, die Ihr durch Eure Fähigkeiten und Angriffe verbraucht, erhaltet Ihr eine Aufladung von 'Tigeraugengebräu'. Setzt 'Tigeraugengebräu' ein, um diese Aufladungen aufzuzehren und Euren verursachten Schaden 15 Sek. lang um [1.6 * (( 90 > 79 ? 1 : 0)) + 3.5]% zu erhöhen.\n\n'Tigeraugengebräu' ist bis zu 20-mal stapelbar, kann jedoch jeweils nur 10 Stapel verbrauchen, um so eine maximale Schadenserhöhung von [(1.6 * (( 90 > 79 ? 1 : 0)) + 3.5) * 10]% zu erhalten." }
entries[1247280] = { ["name"] = "Meisterschaft: Aufgestaute Wut", ["text"] = "Außerhalb von Arenen und Schlachtfeldern:\nGewährt zusätzlich [1.6 * (( 90 > 79 ? 1 : 0)) + 3.5]% Schaden pro Stapel von 'Tigeraugengebräu'\n\nInnerhalb von Arenen und auf Schlachtfeldern:\nWenn Ihr eine Aufladung von 'Tigeraugengebräu' erzeugt, besteht eine Chance von 20%, eine weitere Aufladung zu erzeugen." }
