entries[1248663] = { ["name"] = "Siegel der Einsicht", ["text"] = "Sofort\nErfüllt Euch mit heiligem Licht, das Euer [ Schutz : Nahkampf- und ]Zaubertempo um 10% und Eure gewirkte Heilung um 5% erhöht und Euren Nahkampfangriffen eine Chance gewährt, [ Glyphe 'Schlachtenheiler' : das am schwersten verletzte Gruppen- oder Schlachtzugsmitglied / Euch] um [ Heilige Einsicht : [(0.15 * Angriffskraft + 0.15 * Zaubermacht) * 1.25] / (0.15 * Angriffskraft + 0.15 * Zaubermacht)] [ Heilig : zu heilen und 6% der Grundmanakosten wiederherzustellen, wenn Ihr ein Ziel außerhalb einer Arena oder eines Schlachtfelds trefft ]" }
entries[1248753] = { ["name"] = "Traum des Cenarius", ["text"] = "Sofort\n'Heilende Berührung' erhöht den Schadensbonus Eurer nächsten Finsternis um 25%." }
entries[1248969] = { ["name"] = "Klingenwirbel", ["text"] = "100 Meter Reichweite\nSofort\nBei Aktivierung treffen Eure Angriffe bis zu 4 weitere Gegner in der Nähe und fügen ihnen 40% des normalen Schadens zu. [ Glyphe 'Klingenwirbel' : Eure Chance, Gegner mit nicht-tödlichen Giften zu vergiften, wird um 0% erhöht ] Eure Energieregeneration wird jedoch um 20% verringert. Hält bis Abbruch an." }
