entries[1249613] = { ["name"] = "Zerschmetternder Hieb", ["text"] = "30 Meter Reichweite\nSofort 5 min Abklingzeit\nEin Schlag nach dem Ziel, der dessen Rüstung zerschmettert, 12 Schaden verursacht und seine Rüstung 10 Sek. lang um 20% verringert oder jegliche Unverwundbarkeitseffekte entfernt. Der Einsatz dieser Fähigkeit aktiviert Katzengestalt." }
